add_filter( 'woocommerce_cart_item_price', 'perfectpixel_regular_and_sale_price_in_cart', 30, 3 );

function perfectpixel_regular_and_sale_price_in_cart( $price_html, $cart_item, $cart_item_key ) {
	$product = $cart_item['data'];
	if ( ! $product || ! $product->is_on_sale() ) {
		return $price_html;
	}
	$regular = wc_get_price_to_display( $product, array( 'price' => $product->get_regular_price() ) );
	$active  = wc_get_price_to_display( $product );
	return $regular > $active ? wc_format_sale_price( $regular, $active ) : $price_html;
}
